command(node -e '
const fs = require("fs");
const path = require("path");
function scan(dir) {
  for (const item of fs.readdirSync(dir)) {
    const full = path.join(dir, item);
    if (fs.statSync(full).isDirectory()) {
      if (item !== ".obsidian") scan(full);
    } else {
      if (item.includes("未命名")) console.log("Found:", full);
    }
  }
}
scan("D:/Obsidian/PARA");
console.log("Scan PARA complete.");
')
